# constants
age = 52
temperature = 37.8
systolic_bp = 115
heart_rate = 98
respiratory_rate = 21
fio2 = 33  # as a percentage
paO2 = 68
serum_sodium = 141
hematocrit = 35.5  # as a percentage
chronic_conditions = 0

# APACHE II scoring components
def age_score(age):
    if age < 35:
        return 0
    elif 35 <= age <= 44:
        return 1
    elif 45 <= age <= 54:
        return 2
    elif 55 <= age <= 64:
        return 3
    elif 65 <= age <= 74:
        return 4
    else:
        return 5

def temp_score(temp):
    if 36.1 <= temp <= 37.9:
        return 0
    elif 38.0 <= temp <= 39.9:
        return 1
    elif temp > 40:
        return 2
    else:
        return 3

def bp_score(systolic_bp):
    if systolic_bp > 150:
        return 0
    elif 100 <= systolic_bp <= 150:
        return 1
    else:
        return 2

def hr_score(heart_rate):
    if 40 <= heart_rate <= 100:
        return 0
    elif 101 <= heart_rate <= 140:
        return 1
    elif 141 <= heart_rate <= 180:
        return 2
    else:
        return 3

def rr_score(respiratory_rate):
    if 12 <= respiratory_rate <= 20:
        return 0
    elif 21 <= respiratory_rate <= 29:
        return 1
    else:
        return 2

def paO2_score(paO2, fio2):
    ratio = paO2 / (fio2 / 100)
    if ratio > 300:
        return 0
    elif 200 <= ratio <= 300:
        return 1
    elif 100 <= ratio <= 200:
        return 2
    else:
        return 3

def sodium_score(serum_sodium):
    if serum_sodium < 135:
        return 1
    elif 135 <= serum_sodium <= 145:
        return 0
    else:
        return 1

def hct_score(hematocrit):
    if hematocrit < 30:
        return 1
    elif 30 <= hematocrit <= 44:
        return 0
    else:
        return 1

def chronic_score(chronic_conditions):
    return chronic_conditions

# computation
age_points = age_score(age)
temp_points = temp_score(temperature)
bp_points = bp_score(systolic_bp)
hr_points = hr_score(heart_rate)
rr_points = rr_score(respiratory_rate)
paO2_points = paO2_score(paO2, fio2)
sodium_points = sodium_score(serum_sodium)
hct_points = hct_score(hematocrit)
chronic_points = chronic_score(chronic_conditions)

result = age_points + temp_points + bp_points + hr_points + rr_points + paO2_points + sodium_points + hct_points + chronic_points
